(* [comment removed for export] *)
Lemma pch_facts : forall c c' p n p' E',
  pcore_ok c -> pc_state c = 8 -> pc_hlim c <= 8192 -> pc_skip c < 2^62 -> 0 <= n < 2^62 ->
  pch_out c c' p n p' E' ->
  pcore_ok c' /\ pc_skip c' < 2^62 /\ ec_ok E' /\ (E' = EC_clear \/ http_fail E')
  /\ (ec_failed E' = false -> pc_skip c' = 0 /\ p + 2 <= p' /\ ((pc_state c' = 9 /\ 1 <= pc_len c' /\ pc_hlim c' = pc_hlim c) \/ (pc_state c' = 10 /\ pc_hlim c' = pc_hlim c + 2)))
  /\ (ec_failed E' = true -> p' = p /\ pc_state c' = 8 /\ pc_hlim c' = pc_hlim c)
  /\ p <= p' <= p + n /\ 8 <= pc_state c'.
Proof.
  intros c c' p n p' E' PCOK ST8 HL SK N OUT.
  destruct (pch_out_ok _ _ _ _ _ _ PCOK HL SK N OUT) as [PCOK' SK'].
  split; [exact PCOK'|]. split; [exact SK'|].
  destruct OUT as [(-> & S) | (-> & Fl)].
  - destruct S as (P1 & SK0 & FF & LN & LN0 & BH & BL & ST).
    split; [unfold ec_ok, EC_clear; cbn; lia|]. split; [left; reflexivity|].
    split; [intros _; split; [exact SK0|]; split; [lia|]; destruct ST as [(A1 & A2 & A3)|(A1 & A2 & A3)]; [left | right]; repeat split; try assumption; lia|].
    split; [intros K; exfalso; discriminate K|]. split; [lia|]. destruct ST as [(A1 & _)|(A1 & _)]; rewrite A1; lia.
  - destruct Fl as (F1 & F2 & F3 & F4 & F5 & F6 & F7 & F8 & F9 & F10 & F11 & F12 & F13 & F14).
    split; [exact F3|].
    split. { right. unfold http_fail. split; [exact F1|]. split; [exact F2|]. split; [exact F3|]. split; [exact F4|].
             clear - F5. cbn in F5. unfold HE_NEED_MORE, HE_BAD_CHUNK, HE_BAD_LINE_ENDING, HE_BAD_CHUNK_EXTENSION, HE_BODY_LIMIT in F5. lia. }
    split; [intros K; exfalso; rewrite F2 in K; discriminate K|].
    split; [intros _; rewrite F6, F8, ST8; repeat split; reflexivity|]. rewrite F6, ST8. lia.
Qed.
